#!/usr/bin/env python3
"""Gate C15 Q2: D5 (and D4) as a share of the batch window, from results/analysis/gate_e/e1/partb_phase_totals.csv (C1 arm, 595.91.07, 5070 Ti).
Ratio of medians (the statistic of record, CS2-1) and median of per-run ratios. Evidence ids: E1PartB.<workload>.D5, E1PartB.<workload>.window (D4 has no extract id)."""
import csv, statistics as st
rows = list(csv.DictReader(open("results/analysis/gate_e/e1/partb_phase_totals.csv")))
out = ["# C15 Q2: phase shares on 595.91.07 (generated by `tests/c15_phase_shares.py`)", "", "Source: `results/analysis/gate_e/e1/partb_phase_totals.csv`, arm C1 (prefetcher on, no speculation) and C6-L4096 (arm `C64096`). window = servicing window per run. n = runs per cell.", "",
       "| workload | arm | n | D5 / window (ratio of medians) | D5 / window (median of ratios) | D4 / window (ratio of medians) | D4 / window (median of ratios) | evidence ids |", "|---|---|---|---|---|---|---|---|"]
res = {}
for wl in ("stencil", "graphbfs"):
    for arm in ("C1", "C64096"):
        r = [x for x in rows if x["workload"] == wl and x["arm"] == arm]
        f = lambda k: [float(x[k]) for x in r]
        d5, d4, w = f("D5"), f("D4"), f("window")
        a = (st.median(d5) / st.median(w), st.median(a / b for a, b in zip(d5, w)), st.median(d4) / st.median(w), st.median(a / b for a, b in zip(d4, w)))
        res[(wl, arm)] = a
        out.append(f"| {wl} | {arm} | {len(r)} | {100*a[0]:.2f}% | {100*a[1]:.2f}% | {100*a[2]:.2f}% | {100*a[3]:.2f}% | `E1PartB.{wl}.D5`, `E1PartB.{wl}.window` |")
lo, hi = 52.1, 76.9
c1 = [res[("stencil", "C1")][0] * 100, res[("graphbfs", "C1")][0] * 100]
out += ["", f"Quoted in Section III for the 5070 Ti (driver 595.84): 52--77% (CS2-1: 52.1-76.9%, UNCHECKED); T4 63--74% (UNCHECKED).", f"595.91.07, C1, D5 share of the window (ratio of medians): Stencil-24K {c1[0]:.2f}%, GraphBFS-23 {c1[1]:.2f}%. Inside the quoted 5070 Ti range [{lo}, {hi}]%: Stencil {'yes' if lo <= c1[0] <= hi else 'NO'}, GraphBFS {'yes' if lo <= c1[1] <= hi else 'NO'}.",
        "D4 includes D5 (D4_minus_D5 is the residual, ~33 ms stencil); the share of D4 alone is reported for completeness. The T4 range and the 595.84 range themselves are not recomputed here (their data are the Phase C runs, not committed as CSVs used by this script): they stay UNCHECKED."]
open("results/analysis/consolidation/C15_PHASE_SHARES.md", "w").write("\n".join(out) + "\n")
print("\n".join(out[4:10]))
